use std::sync::{Arc, RwLock, atomic::{AtomicBool, AtomicU64, Ordering}};
use std::collections::HashMap;
use std::thread;
use std::time::Duration;

#[derive(Clone, Debug)]
pub struct FeatureFlags {
    pub enable_new_tokenizer: bool,
    pub enable_parallel_indexing: bool,
    pub max_batch_size: usize,
}

pub struct SearchIndex {
    documents: RwLock<HashMap<u64, IndexedDocument>>,
    pending_batch: RwLock<Vec<RawDocument>>,
    flags: RwLock<FeatureFlags>,
    batch_sequence: AtomicU64,
    is_indexing: AtomicBool,
}

#[derive(Clone, Debug)]
pub struct RawDocument {
    pub id: u64,
    pub content: String,
    pub priority: u8,
}

#[derive(Clone, Debug)]
pub struct IndexedDocument {
    pub id: u64,
    pub tokens: Vec<String>,
    pub indexed_with_new_tokenizer: bool,
    pub batch_id: u64,
}

impl SearchIndex {
    pub fn new(flags: FeatureFlags) -> Arc<Self> {
        Arc::new(Self {
            documents: RwLock::new(HashMap::new()),
            pending_batch: RwLock::new(Vec::new()),
            flags: RwLock::new(flags),
            batch_sequence: AtomicU64::new(0),
            is_indexing: AtomicBool::new(false),
        })
    }

    pub fn update_flags(&self, new_flags: FeatureFlags) {
        let mut flags = self.flags.write().unwrap();
        *flags = new_flags;
    }

    pub fn submit_document(&self, doc: RawDocument) {
        let mut batch = self.pending_batch.write().unwrap();
        let flags = self.flags.read().unwrap();
        if batch.len() < flags.max_batch_size {
            batch.push(doc);
        }
    }

    pub fn flush_batch(&self) -> u64 {
        let batch_id = self.batch_sequence.fetch_add(1, Ordering::SeqCst);
        let flags_snapshot = self.flags.read().unwrap().clone();
        drop(self.flags.read());

        self.is_indexing.store(true, Ordering::Release);

        let batch: Vec<RawDocument> = {
            let mut pending = self.pending_batch.write().unwrap();
            pending.drain(..).collect()
        };

        if flags_snapshot.enable_parallel_indexing {
            self.index_parallel(batch, batch_id, &flags_snapshot);
        } else {
            self.index_sequential(batch, batch_id, &flags_snapshot);
        }

        self.is_indexing.store(false, Ordering::Release);
        batch_id
    }

    fn index_parallel(&self, batch: Vec<RawDocument>, batch_id: u64, flags: &FeatureFlags) {
        let use_new_tokenizer = flags.enable_new_tokenizer;
        let chunks: Vec<Vec<RawDocument>> = batch.chunks(4).map(|c| c.to_vec()).collect();

        let results: Vec<IndexedDocument> = chunks.into_iter().flat_map(|chunk| {
            chunk.into_iter().map(move |doc| {
                let current_flags = self.flags.read().unwrap();
                let tokenizer_flag = current_flags.enable_new_tokenizer;
                drop(current_flags);
                let tokens = if tokenizer_flag {
                    Self::new_tokenize(&doc.content)
                } else {
                    Self::legacy_tokenize(&doc.content)
                };
                IndexedDocument {
                    id: doc.id,
                    tokens,
                    indexed_with_new_tokenizer: tokenizer_flag,
                    batch_id,
                }
            }).collect::<Vec<_>>()
        }).collect();

        let mut docs = self.documents.write().unwrap();
        for indexed in results {
            docs.insert(indexed.id, indexed);
        }
    }

    fn index_sequential(&self, batch: Vec<RawDocument>, batch_id: u64, flags: &FeatureFlags) {
        let mut docs = self.documents.write().unwrap();
        for doc in batch {
            let tokens = if flags.enable_new_tokenizer {
                Self::new_tokenize(&doc.content)
            } else {
                Self::legacy_tokenize(&doc.content)
            };
            docs.insert(doc.id, IndexedDocument {
                id: doc.id,
                tokens,
                indexed_with_new_tokenizer: flags.enable_new_tokenizer,
                batch_id,
            });
        }
    }

    fn new_tokenize(content: &str) -> Vec<String> {
        content.split_whitespace()
            .map(|s| s.to_lowercase().trim_matches(|c: char| !c.is_alphanumeric()).to_string())
            .filter(|s| !s.is_empty())
            .collect()
    }

    fn legacy_tokenize(content: &str) -> Vec<String> {
        content.split_whitespace().map(|s| s.to_string()).collect()
    }

    pub fn search(&self, query: &str) -> Vec<u64> {
        let docs = self.documents.read().unwrap();
        let flags = self.flags.read().unwrap();
        let query_tokens = if flags.enable_new_tokenizer {
            Self::new_tokenize(query)
        } else {
            Self::legacy_tokenize(query)
        };
        drop(flags);

        docs.iter()
            .filter(|(_, doc)| {
                query_tokens.iter().any(|qt| doc.tokens.contains(qt))
            })
            .map(|(id, _)| *id)
            .collect()
    }

    pub fn verify_consistency(&self) -> Vec<u64> {
        let docs = self.documents.read().unwrap();
        let flags = self.flags.read().unwrap();
        docs.iter()
            .filter(|(_, doc)| doc.indexed_with_new_tokenizer != flags.enable_new_tokenizer)
            .map(|(id, _)| *id)
            .collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_race_condition_exposure() {
        let flags = FeatureFlags {
            enable_new_tokenizer: false,
            enable_parallel_indexing: true,
            max_batch_size: 100,
        };
        let index = SearchIndex::new(flags);

        for i in 0..20 {
            index.submit_document(RawDocument {
                id: i,
                content: format!("Hello World document {}", i),
                priority: 1,
            });
        }

        let index_clone = index.clone();
        let handle = thread::spawn(move || {
            index_clone.flush_batch()
        });

        thread::sleep(Duration::from_micros(50));
        index.update_flags(FeatureFlags {
            enable_new_tokenizer: true,
            enable_parallel_indexing: true,
            max_batch_size: 100,
        });

        handle.join().unwrap();
        let inconsistent = index.verify_consistency();
        println!("Inconsistent documents: {:?}", inconsistent);
    }
}
